"""Message schema helpers for the notification server.

All wire messages are JSON objects: {type: str, payload: dict, timestamp: str}.
"""
from __future__ import annotations

import json
from datetime import datetime, timezone
from typing import Any

VALID_TYPES = {"broadcast", "direct", "system"}


class InvalidMessage(ValueError):
    """Raised when a client sends a malformed or unsupported message."""


def now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def build_message(msg_type: str, payload: dict[str, Any], timestamp: str | None = None) -> dict:
    if msg_type not in VALID_TYPES:
        raise InvalidMessage(f"unsupported type: {msg_type!r}")
    return {
        "type": msg_type,
        "payload": payload,
        "timestamp": timestamp or now_iso(),
    }


def encode(message: dict) -> str:
    return json.dumps(message)


def parse_message(raw: str) -> dict:
    try:
        data = json.loads(raw)
    except (json.JSONDecodeError, TypeError) as exc:
        raise InvalidMessage("message is not valid JSON") from exc

    if not isinstance(data, dict):
        raise InvalidMessage("message must be a JSON object")

    msg_type = data.get("type")
    payload = data.get("payload")
    timestamp = data.get("timestamp")

    if msg_type not in VALID_TYPES:
        raise InvalidMessage(f"unsupported type: {msg_type!r}")
    if not isinstance(payload, dict):
        raise InvalidMessage("payload must be an object")
    if not isinstance(timestamp, str):
        raise InvalidMessage("timestamp must be a string")

    return {"type": msg_type, "payload": payload, "timestamp": timestamp}

import json

import pytest

from notification_server.messages import (
    InvalidMessage,
    build_message,
    encode,
    parse_message,
)


def test_build_message_has_required_fields():
    msg = build_message("broadcast", {"text": "hi"})
    assert msg["type"] == "broadcast"
    assert msg["payload"] == {"text": "hi"}
    assert isinstance(msg["timestamp"], str)


def test_build_message_rejects_unknown_type():
    with pytest.raises(InvalidMessage):
        build_message("shout", {})


def test_parse_message_round_trip():
    original = build_message("system", {"event": "ping"}, timestamp="2026-08-13T00:00:00+00:00")
    parsed = parse_message(encode(original))
    assert parsed == original


@pytest.mark.parametrize("raw", ["not json", "[]", "42", '"str"'])
def test_parse_message_rejects_non_object(raw):
    with pytest.raises(InvalidMessage):
        parse_message(raw)


@pytest.mark.parametrize(
    "data",
    [
        {"type": "unknown", "payload": {}, "timestamp": "t"},
        {"type": "broadcast", "payload": "not-a-dict", "timestamp": "t"},
        {"type": "broadcast", "payload": {}, "timestamp": 123},
        {"payload": {}, "timestamp": "t"},
        {"type": "broadcast", "timestamp": "t"},
    ],
)
def test_parse_message_rejects_bad_schema(data):
    with pytest.raises(InvalidMessage):
        parse_message(json.dumps(data))
